.masdir-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(168deg, #f7f5f1 0%, #f1eee8 55%, #ece8e0 100%);
    border-radius: 18px;
}

.masdir-container * {
    box-sizing: border-box;
}

.masdir-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #1a2238 0%, #2b2f55 52%, #6a2233 100%);
    color: #f4f1ea;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(26, 34, 56, 0.30);
    position: relative;
    overflow: hidden;
}

.masdir-header::after {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, #c9a44c 0%, #e7cf8d 50%, #c9a44c 100%);
}

.masdir-header h1 {
    margin: 12px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.masdir-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e7cf8d;
    background: rgba(201, 164, 76, 0.14);
    border: 1px solid rgba(201, 164, 76, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.masdir-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.58;
    color: #d8d3c8;
}

.masdir-context {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
}

.masdir-context-item {
    flex: 1;
    background: #ffffff;
    border-radius: 12px;
    padding: 12px 16px;
    box-shadow: 0 4px 14px rgba(26, 34, 56, 0.07);
    border-left: 4px solid #6a2233;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.masdir-context-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8a7f6b;
}

.masdir-context-val {
    font-size: 0.9rem;
    font-weight: 700;
    color: #1a2238;
    line-height: 1.35;
}

.masdir-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a4d5c;
    margin-bottom: 16px;
    padding: 4px;
}

.masdir-period-counter #currentDay,
.masdir-period-counter #maxPeriods {
    font-weight: 800;
    color: #6a2233;
}

.masdir-round-name {
    background: rgba(106, 34, 51, 0.12);
    color: #6a2233;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.masdir-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #95742a;
    background: rgba(201, 164, 76, 0.16);
    border: 1px solid rgba(201, 164, 76, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.masdir-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.masdir-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(26, 34, 56, 0.08);
    border-top: 4px solid #2b2f55;
}

.masdir-card-enrol { border-top-color: #2b6cb0; }
.masdir-card-margin { border-top-color: #6a2233; }
.masdir-card-completion { border-top-color: #2f855a; }
.masdir-card-demand { border-top-color: #95742a; }

.masdir-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7180;
}

.masdir-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1a2238;
    font-variant-numeric: tabular-nums;
}

.masdir-card-enrol .masdir-value { color: #2b6cb0; }
.masdir-card-margin .masdir-value { color: #6a2233; }
.masdir-card-completion .masdir-value { color: #2f855a; }
.masdir-card-demand .masdir-value { color: #95742a; }

.masdir-sublabel {
    font-size: 0.75rem;
    color: #7c8290;
    line-height: 1.35;
}

/* Danger / good states for the two hard-constraint KPIs. */
.masdir-card-enrol.masdir-kpi-danger { border-top-color: #c53030; }
.masdir-card-enrol.masdir-kpi-danger .masdir-value { color: #c53030; }
.masdir-card-enrol.masdir-kpi-good { border-top-color: #2f855a; }
.masdir-card-enrol.masdir-kpi-good .masdir-value { color: #2f855a; }

.masdir-card-margin.masdir-kpi-danger { border-top-color: #c53030; }
.masdir-card-margin.masdir-kpi-danger .masdir-value { color: #c53030; }
.masdir-card-margin.masdir-kpi-good { border-top-color: #2f855a; }
.masdir-card-margin.masdir-kpi-good .masdir-value { color: #2f855a; }

.masdir-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e4ddd2;
    color: #4a4d5c;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.masdir-threat-bar #threatDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c53030;
    font-weight: 800;
}

.masdir-threat-bar.masdir-threat-low #threatDisplay { color: #2f855a; }
.masdir-threat-bar.masdir-threat-mid #threatDisplay { color: #95742a; }

.masdir-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6a2233;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 56, 0.07);
}

.masdir-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.masdir-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1a2238;
    margin-bottom: 6px;
}

.masdir-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3a3e4c;
}

.masdir-briefing-text strong { color: #6a2233; }
.masdir-briefing-text em { color: #95742a; font-style: italic; }

.masdir-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 56, 0.07);
}

.masdir-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1a2238;
    border-bottom: 2px solid #ece7df;
    padding-bottom: 8px;
}

.masdir-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a2e3c;
    margin: 14px 0 6px;
}

.masdir-container select,
.masdir-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc6ba;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.masdir-container select:focus,
.masdir-container input[type="number"]:focus {
    outline: none;
    border-color: #6a2233;
    box-shadow: 0 0 0 3px rgba(106, 34, 51, 0.15);
}

.masdir-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.masdir-hint {
    font-size: 0.8rem;
    color: #7c8290;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}

.masdir-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.masdir-container .btn-primary {
    background: linear-gradient(135deg, #6a2233 0%, #2b2f55 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(106, 34, 51, 0.30);
}

.masdir-container .btn-primary:hover {
    filter: brightness(1.10);
}

.masdir-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #cdc6ba;
    color: #6b7180;
    background: transparent;
}

.masdir-coach {
    background: linear-gradient(160deg, #1a2238 0%, #2b2f55 100%);
    color: #e7e3d9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(26, 34, 56, 0.24);
}

.masdir-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7cf8d;
    margin-bottom: 8px;
}

.masdir-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.masdir-coach-body strong { color: #e7cf8d; }
.masdir-coach-body em { color: #d9b3bc; font-style: italic; }

.masdir-history,
.masdir-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 56, 0.07);
}

.masdir-history h3,
.masdir-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1a2238;
}

.masdir-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a3e4c;
}

.masdir-container table#usfHistoryTable th {
    background: #f3eee6;
    color: #6a2233;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4dccf;
}

.masdir-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece5;
    color: #3a3e4c;
}

.masdir-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f4;
}

.masdir-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .masdir-container {
        padding: 14px;
    }
    .masdir-header h1 {
        font-size: 1.7rem;
    }
    .masdir-context {
        flex-direction: column;
    }
    .masdir-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .masdir-value {
        font-size: 2.05rem;
    }
    .masdir-clock {
        margin-left: 0;
    }
    .masdir-period-counter {
        font-size: 0.88rem;
    }
    .masdir-threat-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .masdir-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, masdir-cm-*) ===== */
.masdir-cm { color: #22303f; font-family: inherit; }
.masdir-cm-generic { font-size: 15px; text-align: center; }
.masdir-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(34,48,63,0.12); margin-bottom: 16px; }
.masdir-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #34557a; }
.masdir-cm-score-max { font-size: 20px; font-weight: 500; color: #7a8794; margin-left: 2px; }
.masdir-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #22303f; }
.masdir-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #7a8794; margin-top: 4px; }
.masdir-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.masdir-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(52,85,122,0.07); border: 1px solid rgba(52,85,122,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.masdir-cm-kpi-val { display: block; font-size: 20px; font-weight: 700; color: #22303f; }
.masdir-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.masdir-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.masdir-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.masdir-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.masdir-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.masdir-cm-insights { margin: 0; padding-left: 18px; }
.masdir-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #35424e; margin-bottom: 7px; }

