(function() {
    'use strict';

    class MasDirectorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `MAS Director's Dilemma`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Limmat School of Management, CHF). ----
            this.START_ENROL = 71;          // current MAS intake
            this.START_TUITION = 28000;     // CHF per programme
            this.START_VARCOST = 15500;     // CHF variable cost per student (approx)
            this.START_COMPLETION = 81;     // % completion (benchmark 88)
            this.START_DEMAND = 52;         // two-sided demand-fit index 0-100
            this.MIN_COHORT = 60;           // minimum viable cohort
            this.MARGIN_FLOOR = 18;         // % contribution-margin floor
            this.COMPLETION_BENCH = 88;     // % benchmark
            this.FIXED_COST = 720000;       // CHF fixed cost base for the programme
            this.ELASTICITY = 9;            // ~9 enrolments lost per 10% tuition rise
            this.PULL_COEFF = 0.16;         // students drawn per point of demand-fit above baseline
            this.CANNIBAL_HIT = 7;          // students drained when stackability cannibalises the MAS

            // Concept "truths" (the modelled best answers).
            this.TRUE_CAUSE = `combo`;
            this.TRUE_TENSION = `twosided`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    enrol: this.START_ENROL,
                    baseEnrol: this.START_ENROL, // structural enrolment before demand-pull & elasticity
                    tuition: this.START_TUITION,
                    varcost: this.START_VARCOST,
                    completion: this.START_COMPLETION,
                    demand: this.START_DEMAND,
                    margin: 12,                 // current margin (~12% at 71 students)
                    // sticky run-defining penalty flags (gate the top verdict / cap KPIs)
                    misdiagnosed: false,        // wrong root-cause read in R1
                    identityLost: false,        // gutted the generalist core (R2)
                    deficitWidened: false,      // cut price without cutting cost (R3)
                    priceOnlyFix: false,        // raised tuition hard to fix the ratio (R3) — the headline anti-pattern
                    cannibalised: false,        // open stackability drained the full MAS (R2)
                    oneSided: false,            // designed for only one audience (R1/R3)
                    belowCohort: false,         // projected enrolment under 60
                    suspended: false,           // dean moved to suspend/merge
                    // history arrays for the chart (index 0 = baseline)
                    enrolHistory: [this.START_ENROL],
                    marginHistory: [12],
                    completionHistory: [this.START_COMPLETION],
                    demandHistory: [this.START_DEMAND],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the COMMON ERRORS so a blind
                // click-through CANNOT auto-win: price-only diagnosis, gut the core,
                // raise tuition with no cost cut, optimise one audience, defend the ratio.
                state.decisions = {
                    cause: `price`,
                    cohort: `perhead`,
                    tension: `margin`,
                    mix: `gut`,
                    stack: `open`,
                    cost: 17500,
                    tuition: 32000,
                    sequence: `faculty`,
                    audience: `learner`,
                    pitch: `ratio`,
                    competitor: `match`,
                    indicators: `none`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ca = document.getElementById(`causeInput`);
                const co = document.getElementById(`cohortInput`);
                const te = document.getElementById(`tensionInput`);
                if (ca) decisions.cause = ca.value;
                if (co) decisions.cohort = co.value;
                if (te) decisions.tension = te.value;
            } else if (round === 2) {
                const mi = document.getElementById(`mixInput`);
                const st = document.getElementById(`stackInput`);
                const cs = document.getElementById(`costInput`);
                if (mi) decisions.mix = mi.value;
                if (st) decisions.stack = st.value;
                if (cs) decisions.cost = parseFloat(cs.value);
                if (!Number.isFinite(decisions.cost) || decisions.cost < 9000 || decisions.cost > 20000) {
                    warn(`warn_cost_range`); return false;
                }
            } else if (round === 3) {
                const tu = document.getElementById(`tuitionInput`);
                const se = document.getElementById(`sequenceInput`);
                const au = document.getElementById(`audienceInput`);
                if (tu) decisions.tuition = parseFloat(tu.value);
                if (se) decisions.sequence = se.value;
                if (au) decisions.audience = au.value;
                if (!Number.isFinite(decisions.tuition) || decisions.tuition < 20000 || decisions.tuition > 36000) {
                    warn(`warn_tuition_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const cp = document.getElementById(`competitorInput`);
                const ind = document.getElementById(`indicatorsInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (cp) decisions.competitor = cp.value;
                if (ind) decisions.indicators = ind.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let enrolDelta = 0, completionDelta = 0, demandDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the programme (Common Error: misreading the root cause).
                switch (d.cause) {
                    case `combo`: demandDelta += 4; coachKey = `coach_r1_combo`; break;
                    case `price`: ds.misdiagnosed = true; demandDelta -= 2; coachKey = `coach_r1_price`; break;
                    case `marketing`: ds.misdiagnosed = true; demandDelta -= 3; coachKey = `coach_r1_marketing`; break;
                    case `fad`: ds.misdiagnosed = true; demandDelta -= 5; coachKey = `coach_r1_fad`; break;
                }

                switch (d.cohort) {
                    case `floor`: demandDelta += 2; if (d.cause === `combo`) coachKey = `coach_r1_sharp`; break;
                    case `perhead`: ds.misdiagnosed = true; demandDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_perhead`; break;
                    case `ignore`: demandDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r1_cohortignore`; break;
                }

                switch (d.tension) {
                    case `twosided`: demandDelta += 5; break;
                    case `employeronly`: ds.oneSided = true; demandDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r1_employeronly`; break;
                    case `margin`: demandDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r1_marginframe`; break;
                }

                summaryKey = (d.cause === `combo` && d.cohort === `floor` && d.tension === `twosided`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the curriculum mix (Common Errors: identity loss, cannibalising stackability).
                switch (d.mix) {
                    case `rebalance`: demandDelta += 12; completionDelta += 2; coachKey = `coach_r2_rebalance`; break;
                    case `gut`:
                        // Identity loss — the credential stops being a Master's.
                        ds.identityLost = true;
                        demandDelta += 4;          // employers briefly pleased
                        completionDelta -= 1;
                        coachKey = `coach_r2_gut`;
                        break;
                    case `freeze`:
                        // Changed nothing employers complained about — relevance gap persists.
                        demandDelta -= 6;
                        coachKey = `coach_r2_freeze`;
                        break;
                }

                switch (d.stack) {
                    case `designed`: demandDelta += 8; enrolDelta += 3; coachKey = (d.mix === `rebalance`) ? `coach_r2_designed` : coachKey; break;
                    case `open`:
                        // Cannibalises the full-MAS revenue — best students exit early.
                        ds.cannibalised = true;
                        demandDelta += 2;
                        coachKey = `coach_r2_open`;
                        break;
                    case `none`: demandDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_nostack`; break;
                }

                // Variable-cost choice. Taking cost out protects margin; over-building hurts it.
                ds.varcost = Math.max(9000, Math.min(20000, Math.round(d.cost)));
                if (ds.varcost <= 12500) { demandDelta -= 2; }   // cutting cost too hard risks the experience
                if (ds.varcost >= 18000) { /* margin pressure handled in margin calc */ }

                summaryKey = (d.mix === `rebalance` && d.stack === `designed`) ? `sum_r2_good` :
                             (d.mix === `gut` ? `sum_r2_identity` :
                             (d.stack === `open` ? `sum_r2_cannibal` : `sum_r2_weak`));
            } else if (round === 3) {
                // Price and sequence (Common Errors: price-only fix, volume-only discount, sequencing neglect).
                ds.tuition = Math.max(20000, Math.min(36000, Math.round(d.tuition)));
                // Elasticity itself is applied as a LEVEL effect below (from current tuition),
                // so a price rise always bites against the cohort floor and cannot be washed out.

                // A real cut only works if cost came out of the base (Round 2).
                if (ds.tuition < this.START_TUITION - 1500) {
                    const costCut = this.START_VARCOST - ds.varcost; // positive if cost was reduced
                    if (costCut < 1500) {
                        // Volume-only discounting without a matching cost redesign — widen the deficit.
                        ds.deficitWidened = true;
                        coachKey = `coach_r3_pricecut`;
                    } else {
                        // Disciplined cut: cost out AND price down rebuilds volume sustainably.
                        coachKey = `coach_r3_disciplined`;
                    }
                } else if (ds.tuition >= this.START_TUITION + 3500) {
                    // The HEADLINE anti-pattern (Common Error #1): a price-only margin fix —
                    // lifting tuition hard to repair the ratio. The facilitator decision tree
                    // pins this at the CHF 32,000 trip-wire ("below the 60-student minimum viable
                    // cohort"). It is a sticky, run-defining flag so a later strong round cannot
                    // wash it out: improving the per-head ratio while pricing the cohort away
                    // cannot earn the top verdict.
                    ds.priceOnlyFix = true;
                    coachKey = `coach_r3_priceraise`;
                } else if (ds.tuition > this.START_TUITION + 1500) {
                    // A modest, disciplined raise (toward ~CHF 30,000) — a coach nudge, not a fatal flag.
                    coachKey = `coach_r3_priceraise`;
                }

                // Sequencing — drives completion AND cash-flow smoothing.
                switch (d.sequence) {
                    case `quickwins`: completionDelta += 9; coachKey = (coachKey === `coach_default`) ? `coach_r3_sequence` : coachKey; break;
                    case `faculty`: completionDelta -= 3; demandDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r3_seqfaculty`; break;
                    case `capstonefirst`: completionDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r3_seqcapstone`; break;
                }

                // Reconcile the two audiences.
                switch (d.audience) {
                    case `both`: demandDelta += 6; enrolDelta += 2; break;
                    case `learner`: ds.oneSided = true; demandDelta -= 3; enrolDelta -= 2; if (coachKey === `coach_default` || coachKey === `coach_r3_sequence`) coachKey = `coach_r3_learneronly`; break;
                    case `employer`: ds.oneSided = true; demandDelta -= 2; enrolDelta -= 2; if (coachKey === `coach_default` || coachKey === `coach_r3_sequence`) coachKey = `coach_r3_employeronly`; break;
                }

                summaryKey = ds.priceOnlyFix ? `sum_r3_priceonly` :
                             (d.sequence === `quickwins` && d.audience === `both` && !ds.deficitWidened) ? `sum_r3_good` :
                             (ds.deficitWidened ? `sum_r3_deficit` :
                             (d.sequence === `faculty` || d.sequence === `capstonefirst` ? `sum_r3_sequence` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the redesign before the dean's office.
                switch (d.pitch) {
                    case `system`: demandDelta += 4; coachKey = `coach_r4_system`; break;
                    case `ratio`: demandDelta -= 3; coachKey = `coach_r4_ratio`; break;
                    case `identity`: demandDelta -= 2; coachKey = `coach_r4_identityonly`; break;
                }

                switch (d.competitor) {
                    case `differentiate`: demandDelta += 6; enrolDelta += 2; if (coachKey === `coach_r4_system`) coachKey = `coach_r4_differentiate`; break;
                    case `match`:
                        // Price war against a cheaper stack with a heavier cost base — deficit.
                        if (ds.tuition - ds.varcost < 13000) ds.deficitWidened = true;
                        demandDelta -= 2; coachKey = `coach_r4_match`; break;
                    case `ignore`: demandDelta -= 4; enrolDelta -= 2; coachKey = `coach_r4_compignore`; break;
                }

                switch (d.indicators) {
                    case `funnel`: demandDelta += 4; break;
                    case `vanity`: demandDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r4_vanity`; break;
                    case `none`: demandDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r4_noind`; break;
                }

                if (d.conviction >= 60) { demandDelta += 2; }
                else if (d.conviction <= 25) { demandDelta -= 2; }

                summaryKey = (d.pitch === `system` && d.competitor === `differentiate` && d.indicators === `funnel`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply structural deltas. enrolDelta feeds the STRUCTURAL base; the
            // displayed enrolment is then recomputed each round as a LEVEL so that
            // price elasticity and demand-fit always bite against the current design
            // and a single good round cannot wash out a run-defining error. ----
            ds.baseEnrol = Math.max(0, Math.round((ds.baseEnrol + enrolDelta) * 10) / 10);
            ds.completion = Math.max(40, Math.min(100, Math.round((ds.completion + completionDelta) * 10) / 10));
            ds.demand = Math.max(0, Math.min(100, Math.round(ds.demand + demandDelta)));

            // Demand-fit pull (level): a more relevant, two-sided, well-sequenced design
            // draws applicants. Applied from Round 2 onward (after the mix exists).
            const demandPull = (round >= 2) ? (ds.demand - this.START_DEMAND) * this.PULL_COEFF : 0;

            // Price elasticity (level): ~9 enrolments per 10% move from the CHF 28,000 baseline.
            const pctMove = (ds.tuition - this.START_TUITION) / this.START_TUITION; // + = rise
            const elasticEnrol = -(pctMove / 0.10) * this.ELASTICITY;

            // Cannibalisation: open stackability quietly drains the full-MAS cohort.
            const cannibalHit = ds.cannibalised ? this.CANNIBAL_HIT : 0;

            ds.enrol = Math.max(0, Math.round((ds.baseEnrol + demandPull + elasticEnrol - cannibalHit) * 10) / 10);

            // ---- Margin is DERIVED from the system: price, cost, volume vs fixed costs. ----
            const headEnrol = Math.max(1, ds.enrol);
            const contributionPerStudent = ds.tuition - ds.varcost;
            const totalContribution = contributionPerStudent * headEnrol - this.FIXED_COST;
            const totalRevenue = ds.tuition * headEnrol;
            ds.margin = Math.round((totalContribution / totalRevenue) * 1000) / 10; // % to 1 dp
            ds.margin = Math.max(-40, Math.min(45, ds.margin));

            // ---- Sticky-gate caps. ----
            // Below the minimum viable cohort: fixed costs aren't covered; margin can't be "healthy".
            ds.belowCohort = ds.enrol < this.MIN_COHORT;
            if (ds.belowCohort) {
                ds.margin = Math.min(ds.margin, 14); // structurally cannot reach the 18% floor under cohort
            }
            // Identity loss caps demand fit: a "pile of certificates" can't command MAS-level two-sided value.
            if (ds.identityLost) {
                ds.demand = Math.min(ds.demand, 58);
            }
            // Deficit widened (cut price, kept cost) caps margin hard.
            if (ds.deficitWidened) {
                ds.margin = Math.min(ds.margin, 10);
            }

            ds.enrolHistory.push(Math.round(ds.enrol));
            ds.marginHistory.push(ds.margin);
            ds.completionHistory.push(Math.round(ds.completion));
            ds.demandHistory.push(Math.round(ds.demand));

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            // Escalation: if after the final round the September intake still misses the
            // floor on cohort OR margin, the dean's office moves to suspend/merge.
            if (round === 4) {
                ds.suspended = (ds.enrol < this.MIN_COHORT) || (ds.margin < this.MARGIN_FLOOR);
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                enrol: Math.round(ds.enrol),
                enrolDelta: Math.round(enrolDelta * 10) / 10,
                margin: ds.margin,
                tuition: ds.tuition,
                completion: Math.round(ds.completion),
                completionDelta: Math.round(completionDelta * 10) / 10,
                demand: Math.round(ds.demand),
                demandDelta: Math.round(demandDelta),
                belowCohort: ds.belowCohort,
                identityLost: ds.identityLost,
                deficitWidened: ds.deficitWidened,
                priceOnlyFix: ds.priceOnlyFix,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _viabilityLabel(ds) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const safe = ds.enrol >= this.MIN_COHORT && ds.margin >= this.MARGIN_FLOOR;
            const close = ds.enrol >= this.MIN_COHORT && ds.margin >= (this.MARGIN_FLOOR - 4);
            if (safe) return t(`viab_safe`);
            if (close) return t(`viab_close`);
            return t(`viab_risk`);
        }

        _fmtMargin(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `%`;
        }

        _fmtChf(v) {
            // CHF with thousands separators.
            const n = Math.round(Number(v));
            return `CHF ` + n.toLocaleString(`de-CH`).replace(/’/g, `'`).replace(/[\s.]/g, `,`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`enrolDisplay`, `domainState.enrol`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.masdir-card-enrol`);
                if (card) {
                    card.classList.toggle(`masdir-kpi-danger`, n < self.MIN_COHORT);
                    card.classList.toggle(`masdir-kpi-good`, n >= self.MIN_COHORT + 10);
                }
                return `${n}`;
            });

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.masdir-card-margin`);
                if (card) {
                    card.classList.toggle(`masdir-kpi-danger`, n < self.MARGIN_FLOOR);
                    card.classList.toggle(`masdir-kpi-good`, n >= self.MARGIN_FLOOR);
                }
                return self._fmtMargin(n);
            });

            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`demandDisplay`, `domainState.demand`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`threatDisplay`, `domainState.margin`, () => {
                const ds = window.mySimulation.state.domainState;
                const bar = document.querySelector(`.masdir-threat-bar`);
                const safe = ds.enrol >= self.MIN_COHORT && ds.margin >= self.MARGIN_FLOOR;
                const close = ds.enrol >= self.MIN_COHORT && ds.margin >= (self.MARGIN_FLOOR - 4);
                if (bar) {
                    bar.classList.toggle(`masdir-threat-low`, safe);
                    bar.classList.toggle(`masdir-threat-mid`, !safe && close);
                }
                return self._viabilityLabel(ds);
            });
        }

        getChartConfig() {
            return {
                masdirChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_enrol`) : `Enrolment (students)`,
                                data: [],
                                borderColor: `#2b6cb0`,
                                backgroundColor: `rgba(43,108,176,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2b6cb0`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_margin`) : `Contribution margin (%)`,
                                data: [],
                                borderColor: `#6a2233`,
                                backgroundColor: `rgba(106,34,51,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a2233`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_completion`) : `Completion rate (%)`,
                                data: [],
                                borderColor: `#2f855a`,
                                backgroundColor: `rgba(47,133,90,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f855a`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_demand`) : `Two-sided demand fit (0–100)`,
                                data: [],
                                borderColor: `#95742a`,
                                backgroundColor: `rgba(149,116,42,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#95742a`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#4a4d5c`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7c8290` }, grid: { color: `rgba(26,34,56,0.06)` },
                                title: { display: true, text: `students · %`, color: `#7c8290` }
                            },
                            x: {
                                ticks: { color: `#7c8290` }, grid: { color: `rgba(26,34,56,0.04)` },
                                title: { display: true, text: `Round`, color: `#7c8290` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.enrolHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                masdirChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.enrolHistory.map((v) => Math.round(v)) },
                        { data: ds.marginHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.completionHistory },
                        { data: ds.demandHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const enrol = Math.round(ds.enrol);
            const margin = Math.round(ds.margin * 10) / 10;
            const completion = Math.round(ds.completion);
            const demand = Math.round(ds.demand);
            const enrolScore = Math.max(0, Math.min(100, (enrol / 90) * 100));
            const marginScore = Math.max(0, Math.min(100, (margin / 24) * 100));
            const completionScore = Math.max(0, Math.min(100, (completion / 92) * 100));
            return Math.round(enrolScore * 0.30 + marginScore * 0.30 + completionScore * 0.18 + demand * 0.22);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const enrol = Math.round(ds.enrol);
            const margin = Math.round(ds.margin * 10) / 10;
            const completion = Math.round(ds.completion);
            const demand = Math.round(ds.demand);

            const viableCohort = enrol >= this.MIN_COHORT;
            const marginHeld = margin >= this.MARGIN_FLOOR;
            const completes = completion >= this.COMPLETION_BENCH;
            const identityKept = !ds.identityLost;
            const twoSided = !ds.oneSided && demand >= 70;

            // Composite (balanced across the four KPIs, normalised to ~0-100).
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.priceOnlyFix || (ds.belowCohort && margin <= 14)) pattern = `priceonly`;
            else if (ds.deficitWidened) pattern = `discount`;
            else if (ds.identityLost) pattern = `identityloss`;
            else if (ds.oneSided) pattern = `onesided`;
            else if (viableCohort && marginHeld && completes && twoSided) pattern = `restored`;

            // The TOP verdict is gated by EVERY hard constraint + no run-defining error.
            let performance = `Programme Suspended`, performanceKey = `grade_suspended`;
            const noFatalFlag = identityKept && !ds.deficitWidened && !ds.cannibalised && !ds.oneSided && !ds.misdiagnosed && !ds.priceOnlyFix;
            if (viableCohort && marginHeld && completes && twoSided && noFatalFlag && composite >= 74) {
                performance = `Programme Restored`; performanceKey = `grade_restored`;
            } else if (ds.priceOnlyFix) {
                performance = `Ratio Fixed, Cohort Priced Away`; performanceKey = `grade_priceonly`;
            } else if (viableCohort && marginHeld && identityKept) {
                performance = `Viable, Identity Intact`; performanceKey = `grade_viable`;
            } else if (viableCohort && marginHeld) {
                performance = `Margin Held, Identity Strained`; performanceKey = `grade_strained`;
            } else if (ds.identityLost && viableCohort) {
                performance = `Relevant but Hollowed`; performanceKey = `grade_hollowed`;
            } else if (ds.deficitWidened) {
                performance = `Deficit Widened`; performanceKey = `grade_deficit`;
            } else if (ds.belowCohort) {
                performance = `Below Viable Cohort`; performanceKey = `grade_belowcohort`;
            } else if (composite >= 55) {
                performance = `Mixed Outcome`; performanceKey = `grade_mixed`;
            }

            const insights = [];
            if (performance === `Programme Restored`) insights.push(window.mySimulation.t(`insight_restored`));
            else if (pattern === `priceonly`) insights.push(window.mySimulation.t(`insight_priceonly`));
            else if (pattern === `discount`) insights.push(window.mySimulation.t(`insight_discount`));
            else if (pattern === `identityloss`) insights.push(window.mySimulation.t(`insight_identityloss`));
            else if (pattern === `onesided`) insights.push(window.mySimulation.t(`insight_onesided`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.belowCohort) insights.push(window.mySimulation.t(`insight_cohort`));
            if (!marginHeld && !ds.belowCohort) insights.push(window.mySimulation.t(`insight_margin_low`));
            if (!completes) insights.push(window.mySimulation.t(`insight_completion`));
            if (ds.cannibalised) insights.push(window.mySimulation.t(`insight_cannibal`));
            if (ds.misdiagnosed) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            if (ds.suspended) insights.push(window.mySimulation.t(`insight_suspended`));

            return {
                enrol: enrol,
                margin: margin,
                completion: completion,
                demand: demand,
                viableCohort: viableCohort,
                marginHeld: marginHeld,
                completes: completes,
                identityKept: identityKept,
                twoSided: twoSided,
                composite: composite,
                pattern: pattern,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="masdir-cm"><p class="masdir-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="masdir-cm-kpi"><span class="masdir-cm-kpi-val">${valStr}</span>`
                + `<span class="masdir-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="masdir-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="masdir-cm">`
                +   `<div class="masdir-cm-scoreband">`
                +     `<div class="masdir-cm-score">${summary.composite}<span class="masdir-cm-score-max">/100</span></div>`
                +     `<div class="masdir-cm-tier">${tier}</div>`
                +     `<div class="masdir-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="masdir-cm-kpis">`
                +     kpi(`cm_kpi_enrol`, String(Math.round(summary.enrol)))
                +     kpi(`cm_kpi_margin`, self._fmtMargin(summary.margin))
                +     kpi(`cm_kpi_completion`, String(Math.round(summary.completion)) + `%`)
                +     kpi(`cm_kpi_demand`, String(Math.round(summary.demand)))
                +   `</div>`
                +   `<div class="masdir-cm-chips">`
                +     chip(summary.viableCohort, `cm_chip_cohort`)
                +     chip(summary.marginHeld, `cm_chip_margin`)
                +     chip(summary.completes, `cm_chip_completion`)
                +     chip(summary.identityKept, `cm_chip_identity`)
                +     chip(summary.twoSided, `cm_chip_demand`)
                +   `</div>`
                +   (insights ? `<ul class="masdir-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.belowCohort) return window.mySimulation.t(`hint_cohort`);
            if (ds.priceOnlyFix) return window.mySimulation.t(`hint_priceonly`);
            if (ds.deficitWidened) return window.mySimulation.t(`hint_deficit`);
            if (ds.identityLost) return window.mySimulation.t(`hint_identity`);
            if (ds.margin < this.MARGIN_FLOOR && state.currentPeriod >= 3) return window.mySimulation.t(`hint_margin`);
            if (ds.oneSided) return window.mySimulation.t(`hint_onesided`);
            if (ds.completion < this.COMPLETION_BENCH && state.currentPeriod >= 3) return window.mySimulation.t(`hint_completion`);
            if (ds.enrol >= this.MIN_COHORT && ds.margin >= this.MARGIN_FLOOR && ds.completion >= this.COMPLETION_BENCH) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.enrol`, label: `Enrolment`, i18nKey: `col_enrol`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => self._fmtMargin(Number(v)) },
                { key: `results.completion`, label: `Completion`, i18nKey: `col_completion`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.demand`, label: `Demand fit`, i18nKey: `col_demand`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
